	// Menu class
	class GameMenu {
	  constructor() {
	    this.main = document.getElementById("main-menu");
	    this.pause = document.getElementById("pause-menu");
	    this.start = document.getElementById("start-btn");
	    this.resume = document.getElementById("resume-btn");
	    this.menu = document.getElementById("menu-btn");
	    if (this.pause) this.pause.style.display = "none";
	    this.active = this.paused = false;
	  }

	  showMain() {
	    if (this.main) this.main.style.display = "flex";
	    if (this.pause) this.pause.style.display = "none";
	    this.active = this.paused = false;
	  }
	  hideMain() {
	    if (this.main) this.main.style.display = "none";
	    this.active = true;
	    this.paused = false;
	  }
	  showPause() {
	    if (this.active && !this.paused && this.pause) {
	      this.pause.style.display = "flex";
	      this.paused = true;
	    }
	  }
	  hidePause() {
	    if (this.pause) this.pause.style.display = "none";
	    this.paused = false;
	  }

	  onStart(cb) {
	    if (this.start) this.start.onclick = cb;
	  }
	  onResume(cb) {
	    if (this.resume) this.resume.onclick = cb;
	  }
	  onExit(cb) {
	    if (this.menu) this.menu.onclick = cb;
	  }

	  onEscape(onP, onR) {
	    document.onkeydown = (e) => {
	      if (e.code === "Escape" && this.active) this.paused ? onR() : onP();
	    };
	  }

	  reset(player, controls) {
	    if (player) {
	      player.setTranslation({ x: 0, y: 10, z: 0 }, true);
	      player.setLinvel({ x: 0, y: 0, z: 0 }, true);
	    }
	    if (controls && controls.isLocked) controls.unlock();
	  }
	}

	// ==========================================
	// ИНИЦИАЛИЗАЦИЯ МЕНЮ
	// ==========================================
	const gameMenu = new GameMenu();
	let isGameActive = false;
	let isPaused = false;

	function setIsGameActive(value) {
	  isGameActive = value;
	}

	function setIsPaused(value) {
	  isPaused = value;
	}

	function menuInit(controls) {
	  gameMenu.onResume(() => {
	    gameMenu.hidePause();
	    isPaused = false;
	    isGameActive = true;
	  });

	  gameMenu.onExit(() => {
	    gameMenu.showMain();
	    isGameActive = isPaused = false;
	    if (controls.isLocked) controls.unlock();
	    gameMenu.reset(playerBody, controls);
	  });

	  gameMenu.onEscape(
	    () => {
	      if (isGameActive && !isPaused) {
	        gameMenu.showPause();
	        isPaused = true;
	        isGameActive = false;
	        if (controls.isLocked) controls.unlock();
	      }
	    },
	    () => {
	      gameMenu.hidePause();
	      isPaused = false;
	      isGameActive = true;
	    },
	  );

	  gameMenu.showMain();
	}

	function isGrounded(RAPIER, world, playerBody, jumpParams) {
	  const pos = playerBody.translation();
	  const ray = new RAPIER.Ray(
	    { x: pos.x, y: pos.y, z: pos.z },
	    { x: 0, y: -1, z: 0 },
	  );
	  const hit = world.castRay(ray, jumpParams.groundCheck, true);
	  return hit !== null;
	}

	function MovePlayer(
	  world,
	  playerBody,
	  jumpParams,
	  camera,
	  PARAMS,
	  moveDirection,
	  frontVector,
	  sideVector,
	  controls,
	  keys,
	  canJump,
	) {
	  // ЛОГИКА ДВИЖЕНИЯ ИГРОКА (Только если курсор мыши захвачен игрой)
	  if (controls.isLocked) {
	    // ПРЫЖОК
	    const grounded = isGrounded(bg, world, playerBody, jumpParams);
	    if (keys.space && grounded && canJump) {
	      const vel = playerBody.linvel();
	      playerBody.setLinvel({ x: vel.x, y: jumpParams.force, z: vel.z }, true);
	      console.log("Прыжок");
	      canJump = false;
	    }
	    if (grounded && !keys.space && !canJump) canJump = true; // защита от повторного прыжка

	    frontVector.set(0, 0, Number(keys.w) - Number(keys.s));
	    sideVector.set(0, 0, Number(keys.d) - Number(keys.a));

	    camera.getWorldDirection(moveDirection);
	    moveDirection.y = 0;
	    moveDirection.normalize();

	    let current_speed;
	    // Ускорение по shift
	    if (keys.shift) current_speed = PARAMS.speed * PARAMS.boost;
	    else current_speed = PARAMS.speed;

	    const targetVelocityX =
	      (moveDirection.x * frontVector.z +
	        camera.up.clone().cross(moveDirection).negate().x * sideVector.z) *
	      current_speed;
	    const targetVelocityZ =
	      (moveDirection.z * frontVector.z +
	        camera.up.clone().cross(moveDirection).negate().z * sideVector.z) *
	      current_speed;

	    const currentYVelocity = playerBody.linvel().y;

	    playerBody.setLinvel(
	      { x: targetVelocityX, y: currentYVelocity, z: targetVelocityZ },
	      true,
	    );
	  }

	  const playerPos = playerBody.translation();
	  camera.position.set(
	    playerPos.x,
	    playerPos.y + jumpParams.playerHeight,
	    playerPos.z,
	  );
	  return canJump;
	}

