	function initAudio(scene, camera, onProgress) {
	  return new Promise((resolve, reject) => {
	    listener = new AudioListener();
	    camera.add(listener);
	    console.log("🎧 Слушатель создан");

	    soundPoint = new Object3D();
	    soundPoint.position.set(0, 0, 0);
	    scene.add(soundPoint);
	    console.log("📌 Источник звука создан в точке:", soundPoint.position);

	    sound = new PositionalAudio(listener);
	    sound.setVolume(1);
	    sound.setRefDistance(20);
	    sound.setMaxDistance(50);
	    sound.setRolloffFactor(1);

	    soundPoint.add(sound);
	    console.log("🔊 Объект звука создан");

	    const audioLoader = new AudioLoader();
	    const audioPath = "./assets/sounds/backrooms.mp3";
	    console.log(`📁 Загрузка аудио: ${audioPath}`);

	    audioLoader.load(
	      "./assets/sounds/backrooms.mp3",
	      (buffer) => {
	        console.log("✅ Аудио загружено, размер:", buffer.length);
	        sound.setBuffer(buffer);
	        sound.play();
	        console.log("▶️ Попытка воспроизведения");
	        resolve();
	      },
	      (progress) => {
	        const percent = (progress.loaded / progress.total) * 100;
	        if (onProgress) onProgress(percent, "Аудио");
	      },
	      (error) => {
	        reject(error);
	        console.error("❌ ОШИБКА загрузки аудио:", error);
	      },
	    );
	    document.addEventListener("click", activateAudio);
	    document.addEventListener("keydown", activateAudio);
	  });
	}

	function activateAudio() {
	  if (!sound || !sound.context) {
	    console.warn("❌ Нет аудио контекста");
	    return;
	  }

	  if (sound.context.state === "suspended") {
	    sound.context
	      .resume()
	      .then(() => {
	        console.log("✅ Аудио контекст активирован");

	        if (sound.buffer && !sound.isPlaying) {
	          sound.play();
	          console.log("▶️ Звук запущен после активации");
	        }
	      })
	      .catch((err) => {
	        console.error("❌ Ошибка активации:", err);
	      });
	  } else if (sound.context.state === "running") {
	    if (sound.buffer && !sound.isPlaying) {
	      sound.play();
	      console.log("▶️ Звук запущен");
	    }
	  }
	}

	class LoadingManager {
	  constructor() {
	    // Находим элементы на странице (они уже есть в index.html)
	    this.screen = document.getElementById("loading-screen");
	    this.progressBar = document.getElementById("progress-bar");
	    this.progressText = document.getElementById("progress-text");
	    this.statusText = document.getElementById("status-text");

	    // Список задач загрузки
	    this.tasks = [];
	    // Прогресс каждой задачи (по индексу)
	    this.taskProgress = [];
	    // Общий прогресс
	    this.totalProgress = 0;
	    // Флаг завершения
	    this.isComplete = false;
	  }

	  /**
	   * Добавить задачу загрузки.
	   * @param {Function} taskFn - асинхронная функция, которая принимает колбэк onProgress(percent, status)
	   * @param {string} name - название задачи для отображения
	   */
	  addTask(taskFn, name = "") {
	    this.tasks.push({ fn: taskFn, name });
	    this.taskProgress.push(0); // начальный прогресс 0
	  }

	  /**
	   * Запустить загрузку всех добавленных задач.
	   * @returns {Promise} - разрешается, когда все задачи загружены
	   */
	  async start() {
	    // Показываем экран загрузки
	    this.screen.style.display = "flex";
	    this.screen.style.opacity = "1";
	    this.updateProgress(0, "Инициализация...");

	    const total = this.tasks.length;
	    if (total === 0) {
	      this.complete();
	      return;
	    }

	    // Запускаем все задачи параллельно, каждая передаёт свой колбэк
	    const promises = this.tasks.map((task, index) => {
	      return task.fn((percent, status) => {
	        // Обновляем прогресс конкретной задачи
	        this.taskProgress[index] = percent;
	        // Вычисляем средний прогресс по всем задачам
	        const sum = this.taskProgress.reduce((a, b) => a + b, 0);
	        const avg = sum / total;
	        this.updateProgress(avg, status || `Загрузка: ${task.name}`);
	      });
	    });

	    // Ждём завершения всех
	    await Promise.all(promises);

	    // Все загружено
	    this.complete();
	  }

	  /**
	   * Обновить отображение прогресса.
	   */
	  updateProgress(percent, status) {
	    const clamped = Math.min(percent, 100);
	    this.progressBar.style.width = clamped + "%";
	    this.progressText.textContent = Math.round(clamped) + "%";
	    if (status) this.statusText.textContent = status;
	    this.totalProgress = clamped;
	  }

	  /**
	   * Завершить загрузку (прогресс 100%) и скрыть экран.
	   */
	  complete() {
	    this.updateProgress(100, "✅ Готово!");
	    this.isComplete = true;
	    // Небольшая задержка перед скрытием
	    setTimeout(() => {
	      this.hide();
	    }, 500);
	  }

	  /**
	   * Скрыть экран загрузки с плавным исчезновением.
	   */
	  hide() {
	    this.screen.style.opacity = "0";
	    setTimeout(() => {
	      this.screen.style.display = "none";
	    }, 800);
	  }

	  /**
	   * Сбросить состояние (очистить задачи, сбросить прогресс).
	   */
	  reset() {
	    this.tasks = [];
	    this.taskProgress = [];
	    this.totalProgress = 0;
	    this.isComplete = false;
	    this.progressBar.style.width = "0%";
	    this.progressText.textContent = "0%";
	    this.statusText.textContent = "Подготовка...";
	    this.screen.style.display = "none";
	  }
	}

	function showStory(onWatchVideo) {
	  const storyScreen = document.getElementById("story-screen");
	  if (!storyScreen) return;

	  storyScreen.style.display = "flex";
	  const watchBtn = document.getElementById("watch-video-btn");
	  watchBtn.onclick = () => {
	    storyScreen.style.display = "none";
	    if (typeof onWatchVideo === "function") onWatchVideo();
	  };
	}

	function startVideo(onComplete) {
	  const videoScreen = document.getElementById("video-screen");
	  const video = document.getElementById("story-video");
	  const skipBtn = document.getElementById("skip-video-btn");

	  if (!videoScreen || !video) return;

	  videoScreen.style.display = "block";

	  function finishVideo() {
	    video.pause();
	    video.currentTime = 0;
	    videoScreen.style.display = "none";
	    video.removeEventListener("ended", finishVideo);
	    skipBtn.onclick = null;
	    if (typeof onComplete === "function") onComplete();
	  }

	  video.play().catch((err) => {
	    console.warn("Видео не удалось воспроизвести:", err);
	    finishVideo();
	  });

	  video.addEventListener("ended", finishVideo);
	  skipBtn.onclick = finishVideo;
	}

